@import "@fontsource-variable/archivo/wdth.css";
@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource/dm-mono/400.css";
@import "@fontsource/dm-mono/500.css";

/* Light: the faithful mode. A pale grey #f3f3f3 page with white #fff bands and #e7e7e7
   tiles, pure black ink, and one gold #e9b709 for button frames, active labels and hover
   fills. The site's black bands (hero, model card, panels, footer) are `dark` scopes, so
   they take the `.dark` values below on this light page too. */
:root {
  --background: oklch(0.964 0 0);
  --foreground: oklch(0 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0 0 0);
  --primary: oklch(0.802 0.163 88.6);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.928 0 0);
  --secondary-foreground: oklch(0 0 0);
  --muted: oklch(0.928 0 0);
  --muted-foreground: oklch(0 0 0 / 50%);
  --accent: oklch(0 0 0 / 6%);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.58 0.22 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.833 0 0);
  --input: oklch(0 0 0 / 25%);
  --ring: oklch(0.802 0.163 88.6);
  --highlight: oklch(0.802 0.163 88.6);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.802 0.163 88.6);
  --chart-1: oklch(0.802 0.163 88.6);
  --chart-2: oklch(0 0 0);
  --chart-3: oklch(0.6 0 0);
  --chart-4: oklch(0.833 0 0);
  --chart-5: oklch(0.68 0.13 80);
  --sidebar: oklch(1 0 0);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0 0 0);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0 0 0 / 6%);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0.833 0 0);
  --sidebar-ring: oklch(0.802 0.163 88.6);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Archivo Variable", "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "DM Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 120rem;
  --page-gutter: 0.875rem;
  --section-y: clamp(5rem, 16svh, 10rem);

  /* theme-only: the wide face runs at Archivo's widest (Druk Wide stand-in) */
  --valaratomics-stretch: 125%;
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 5.9vw;
  }
}

/* Dark: the sibling, and the palette of the black bands. Pure black ground, white ink at
   full / 50% / 30%, near-black #1a1a1a raised surfaces, white hairlines at low alpha, the
   same gold, and a white glow (the footer mark's halo). */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.159 0 0);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.159 0 0);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.802 0.163 88.6);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.218 0 0);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.218 0 0);
  --muted-foreground: oklch(1 0 0 / 50%);
  --accent: oklch(1 0 0 / 8%);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.65 0.22 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 18%);
  --input: oklch(1 0 0 / 30%);
  --ring: oklch(0.802 0.163 88.6);
  --highlight: oklch(0.802 0.163 88.6);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(1 0 0);
  --chart-1: oklch(0.802 0.163 88.6);
  --chart-2: oklch(1 0 0);
  --chart-3: oklch(0.6 0 0);
  --chart-4: oklch(0.35 0 0);
  --chart-5: oklch(0.68 0.13 80);
  --sidebar: oklch(0.159 0 0);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.802 0.163 88.6);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(1 0 0 / 8%);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 18%);
  --sidebar-ring: oklch(0.802 0.163 88.6);
}
